cd /app; cat > /tmp/r.py <<'E'
import os,sys
def res(svc,env,host,hist):
    out={}
    def read(path,rel):
        # rel: path relative to /app/config
        p=hist(rel)
        sec=None
        for ln in open(p):
            ln=ln.strip()
            if not ln or ln.startswith('#'):continue
            if ln.startswith('['):sec=ln[1:-1].strip();continue
            k,_,v=ln.partition('=');k=k.strip();v=v.strip()
            if k=='include':
                if sec is not None: continue
                v=v.replace('${env}',env).replace('${host}',host)
                read(None,os.path.normpath(os.path.join(os.path.dirname(rel),v)))
                continue
            if sec is None or sec==svc:
                out[k]=v; 
                if k in('admin_port','port_base','port_offset','enabled'):print(' ',rel,k,v)
    # service.conf
    for ln in open(f'/app/services/{svc}/service.conf'):
        ln=ln.strip()
        if not ln or ln.startswith('#'):continue
        k,_,v=ln.partition('=');k=k.strip();v=v.strip()
        if k=='include':
            read(None,os.path.normpath(os.path.join('services/'+svc,v)).replace('services/'+svc+'/../../','') if False else os.path.normpath(os.path.join('/app/services/'+svc,v))[len('/app/config/'):])
        else: out[k]=v;print(' svc',k,v)
    return out
def hist(R):
    def h(rel):
        for r in range(R+1,500):
            p=f'/app/config-history/r{r:04d}/prev/{rel}'
            if os.path.exists(p):return p
        return '/app/config/'+rel
    return h
R=int(sys.argv[1])
o=res(sys.argv[2],'prod-b','app-07',hist(R))
print({k:o[k] for k in ('admin_port','port_base','port_offset','enabled') if k in o})
